let indirectEval = eval;
class Benchmark {
    async init() {
        this.inspectorText = `let _____top_level_____ = ${Math.random()}; ${await JetStream.getString(JetStream.preload.inspectorPayloadBlob)}`;
        this.index = 0;
    }

    prepareForNextIteration() {
        this.text = `function test${this.index}() { ${this.inspectorText} }`;
        if (this.text[0] !== "f")
            throw new Error;
        if (this.text[this.text.length - 1] !== "}")
            throw new Error;
        this.index = (this.index + 1) % 20;
    }

    runIteration() {
        indirectEval(this.text);
    }
}

